for any $x\in M'$ and~$y\in X$, there exists $(g_n)_{n\geq 1}\subseteq \mathbb{G}$ such that $g_n\to\infty$ and $T_{g_n}y\to x$ as $n\to\infty$,
\item\label{HC}
there exists $x_M\in X$ such that for any $y\in X$ there exists $(g_n)_{n\geq 1}\subseteq \mathbb{G}$ such that $g_n\to\infty$ and $T_{g_n}y\to x_M$,
\item\label{HD}
there exists a closed, $(T_g)_{g\in\mathbb{G}}$-invariant subset $M''\subseteq X$, such that $\left\{g\in\mathbb{G};\right.\\ \left. T_gx_0 \in U\right\}$ is syndetic for any open $U$ with $U\cap M''\neq\emptyset$,
\item\label{HE}
there exists a sequnce of open sets $(U_n)_{n\geq 1}\subseteq X$ such that:
\begin{itemize}
\item
$\text{diam}(U_n)\to 0\text{ as }n\to\infty$,
\item
the set $\{g\in\mathbb{G};\ T_gx_0 \in U_n\}$ is syndetic for each $n\in{\mathbb{N}}$.
\end{itemize}
\end{enumerate}
Furthermore, if any of the above hold, then $M=M'=M''$ and $x_M\in M$.

\label{prime}
Let $m\geq2$ and $\{\Lambda_i\}_{i\geq1}$ be an inifite and pairwise coprime collection of lattices in ${\mathbb{Z}}^m$.
Then $\left\{[{\mathbb{Z}}^m:\Lambda_i]\right\}_{i\geq1}$ contains an infinite pairwise coprime subset.
